using System;
using System.Linq;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace OpenTPW.Tests;

using Vector3 = System.Numerics.Vector3;

/// <summary>
/// The far argument of the original's eye views (<see cref="TerrainEyeViewFar"/>, <c>0x56EA90</c>): reference numbers from an offline emulation of the original's own instructions (the box search, the box test and the initialiser of its outcode table, with the matrix
/// transform of <c>0x87B088</c> replaced by the same clip formula in single precision; analysis scripts outside the repository, tp.exe never launched).
/// </summary>
[TestClass]
public class TerrainEyeViewFarTests
{
	/// <summary>The 128 bytes the original's initialiser <c>0x561840</c> leaves at <c>0x879970</c>.</summary>
	private const string EmulatedOutcodeTable = "00080004202820240008000410181014020a0206222a2226020a0206121a121601090105212921250109010511191115010901052129212501090105111911153e3a3e362e2a2e263e3a3e361e1a1e163e3a3e362e2a2e263e3a3e361e1a1e163f3b3f372f2b2f273f3b3f371f1b1f173d393d352d292d253d393d351d191d15";

	[TestMethod]
	public void TheOutcodeOfEveryIndexIsTheTableTheOriginalBuilds()
	{
		var expected = Convert.FromHexString( EmulatedOutcodeTable );
		// the index is the signs and magnitude compares of w, z, y and x: build a vertex for each of the 128 indexes
		for ( var index = 0; index < 128; index++ )
		{
			float Pick( bool negative, bool beyond ) => (negative ? -1f : 1f) * (beyond ? 2f : 0.5f);
			var w = (index & 64) != 0 ? -1f : 1f;
			var z = Pick( (index & 32) != 0, (index & 16) != 0 );
			var y = Pick( (index & 8) != 0, (index & 4) != 0 );
			var x = Pick( (index & 2) != 0, (index & 1) != 0 );
			// the magnitude compares use |w| = 1: beyond (2) is greater, inside (0.5) is not
			Assert.AreEqual( expected[index], TerrainEyeViewFar.Outcode( x, y, z, w ), $"index {index}" );
		}
	}

	[TestMethod]
	public void AViewOutsideTheFieldKeepsTheWholeRange()
	{
		var field = new TerrainEyeViewFar.Field( 40, 40, 10f, 10f, 0f, 0f, -2f, 10f );
		var view = new TerrainEyeViewFar.View( new Vector3( 5000f, 5f, 5000f ), Vector3.UnitX, Vector3.UnitY, Vector3.UnitZ, 0.5625f, 0.70710678f, 0.70710678f );
		Assert.AreEqual( TerrainEyeViewFar.WholeRange, TerrainEyeViewFar.Compute( field, view, 325f ) );
	}

	[TestMethod]
	public void TheFarArgumentOfTheEmulatedViewsIsReproduced()
	{
		foreach ( var (index, c) in Cases.Select( ( value, index ) => (index, value) ) )
		{
			var view = new TerrainEyeViewFar.View( c.Position, c.Right, c.Up, c.Forward, 0.5625f, 0.70710678f, 0.70710678f );
			Assert.AreEqual( c.Far, TerrainEyeViewFar.Compute( c.Field, view, c.ViewDistance ), c.Far * 1e-5f, $"case {index}" );
		}
		Assert.IsTrue( Cases.Any( c => c.Far > TerrainEyeViewFar.Floor && c.Far < TerrainEyeViewFar.WholeRange ), "some views raise the argument above its floor" );
		Assert.IsTrue( Cases.Any( c => c.Far == TerrainEyeViewFar.Floor ) && Cases.Any( c => c.Far == TerrainEyeViewFar.WholeRange ) );
	}

